param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-digit-substitution-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$property=[Globalization.NumberFormatInfo].GetProperty('DigitSubstitution')
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=[Collections.Generic.List[object]]::new();$enumRows=[Collections.Generic.List[object]]::new();$enumType=[Globalization.DigitShapes];$formatMethod=$enumType.GetMethod('ToString',[type[]]@([string]))
foreach($value in $plan.values){$enum=[Enum]::ToObject($enumType,[int]$value);foreach($format in $plan.formats){$arguments=[object[]]::new(1);$arguments[0]=$format;try{$text=[string]$formatMethod.Invoke($enum,$arguments);$result=[ordered]@{ok=$true;textUnits=[int[]][char[]]$text}}catch{$result=Failure $_};$enumRows.Add([ordered]@{value=[int]$value;format=$format;result=$result})};foreach($seed in $plan.seeds){foreach($mode in $plan.modes){$original=[Globalization.NumberFormatInfo]::new();$property.SetValue($original,[Enum]::ToObject($enumType,[int]$seed));$ro=[Globalization.NumberFormatInfo]::ReadOnly($original);switch($mode){'mutable'{$target=$original};'readonly'{$target=$ro};'clone'{$target=[Globalization.NumberFormatInfo]$ro.Clone()};'invariant'{$target=[Globalization.NumberFormatInfo]::InvariantInfo}};$before=[int]$target.DigitSubstitution;try{$property.SetValue($target,$enum);$result=[ordered]@{ok=$true}}catch{$result=Failure $_};$clone=[Globalization.NumberFormatInfo]$target.Clone();$view=[Globalization.NumberFormatInfo]::ReadOnly($target);$rows.Add([ordered]@{value=[int]$value;seed=[int]$seed;mode=$mode;before=$before;result=$result;after=[int]$target.DigitSubstitution;originalAfter=[int]$original.DigitSubstitution;cloneAfter=[int]$clone.DigitSubstitution;viewAfter=[int]$view.DigitSubstitution;targetReadOnly=$target.IsReadOnly;cloneReadOnly=$clone.IsReadOnly;viewReadOnly=$view.IsReadOnly})}}}
$typeRecord=[ordered]@{fullName=$enumType.FullName;name=$enumType.Name;namespace=$enumType.Namespace;baseType=$enumType.BaseType.FullName;isEnum=$enumType.IsEnum;isValueType=$enumType.IsValueType;isPrimitive=$enumType.IsPrimitive;isSealed=$enumType.IsSealed;underlyingType=[Enum]::GetUnderlyingType($enumType).FullName;names=[Enum]::GetNames($enumType);values=[int[]][Enum]::GetValues($enumType)}
if($rows.Count -ne 156 -or $enumRows.Count -ne 169){throw 'Wrong digit substitution matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';type=$typeRecord;enumRows=$enumRows.ToArray();rows=$rows.ToArray();qualification='SELECTED_DIGITSHAPES_IDENTITY_FORMATTING_AND_DIGITSUBSTITUTION_STATE_ONLY; DIGIT_RENDERING_FULL_ENUM_ABI_CULTURES_METADATA_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 26 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS DigitShapes and DigitSubstitution: 169 enum cases, 156 setter cases'
